            elif o==4: out.append(p[a:a+2])
            elif o==5: out.append(bool(p))
        except Exception as e: out.append(type(e).__name__)
    out.append(list(p)); return out
def ops_seek(M,L,ops):
    s=M.seekable(L); out=[]
    for o,a in ops:
        try:
            if o==0: out.append(s.peek('D'))
            elif o==1: out.append(next(s))
            elif o==2: s.seek(a); out.append('sk')
            elif o==3: s.relative_seek(a-2); out.append('rs')
            elif o==4: out.append(list(s.elements()))
            elif o==5: out.append(bool(s))
        except Exception as e: out.append(type(e).__name__)
